<<<<<<<< SEARCH
CONFIG_ADC=y
CONFIG_ADC_LOG_LEVEL_INF=y
========
CONFIG_ADC=y
CONFIG_ADC_EMUL=y
CONFIG_ADC_LOG_LEVEL_INF=y
